def corners_of(edge):
    h, w = len(edge), len(edge[0])
    n = 0
    for i in range(1, h-1):
        for j in range(1, w-1):
            if not edge[i][j]: continue
            nb = [(a,b) for a in (-1,0,1) for b in (-1,0,1) if (a,b)!=(0,0) and edge[i+a][j+b]]
            if len(nb) == 2 and nb[0][0]*nb[1][0]+nb[0][1]*nb[1][1] == 0:
                n += 1
    return n
